
(function(root){'use strict';
class CombatAudio{
 constructor(context){this.context=context;this.lastVoice=-10;this.noiseCache=new WeakMap();this.randomState302=0x302cafe;}
 random302(){this.randomState302=(Math.imul(this.randomState302,1664525)+1013904223)>>>0;return this.randomState302/4294967296;}
 noise(c){let b=this.noiseCache.get(c);if(!b){b=c.createBuffer(1,c.sampleRate*3,c.sampleRate);const d=b.getChannelData(0);for(let i=0;i<d.length;i++)d[i]=this.random302()*2-1;this.noiseCache.set(c,b);}return b;}
 impact(kind='punch'){const c=this.context();if(!c)return;const now=c.currentTime,flame=kind==='flame',land=kind==='land',knee=kind==='knee',kick=kind==='kick',duration=flame?.32:land?.26:knee?.16:kick?.18:.12,source=c.createBufferSource(),filter=c.createBiquadFilter(),gain=c.createGain();source.buffer=this.noise(c);filter.type=flame?'bandpass':'lowpass';filter.frequency.setValueAtTime(flame?1600:land?240:knee?450:kick?2200:3400,now);if(flame)filter.frequency.exponentialRampToValueAtTime(200,now+duration);gain.gain.setValueAtTime(.001,now);gain.gain.linearRampToValueAtTime(flame?.3:land?.32:.25,now+.006);gain.gain.exponentialRampToValueAtTime(.001,now+duration);source.connect(filter).connect(gain).connect(c.destination);source.start(now,this.random302());source.stop(now+duration);const body=c.createOscillator(),bodyGain=c.createGain();body.type='sine';body.frequency.setValueAtTime(land?80:knee?135:kick?165:flame?110:190,now);body.frequency.exponentialRampToValueAtTime(35,now+duration);bodyGain.gain.setValueAtTime(.24,now);bodyGain.gain.exponentialRampToValueAtTime(.001,now+duration);body.connect(bodyGain).connect(c.destination);body.start();body.stop(now+duration);}
 gunshot(){const c=this.context();if(!c)return;const t=c.currentTime;for(const [delay,duration,volume,hz]of [[0,.12,.48,2800],[.055,.20,.10,1100]]){const n=c.createBufferSource(),f=c.createBiquadFilter(),g=c.createGain();n.buffer=this.noise(c);f.type='highpass';f.frequency.value=hz;g.gain.setValueAtTime(volume,t+delay);g.gain.exponentialRampToValueAtTime(.001,t+delay+duration);n.connect(f).connect(g).connect(c.destination);n.start(t+delay,this.random302());n.stop(t+delay+duration);}const o=c.createOscillator(),g=c.createGain();o.type='triangle';o.frequency.setValueAtTime(160,t);o.frequency.exponentialRampToValueAtTime(45,t+.09);g.gain.setValueAtTime(.28,t);g.gain.exponentialRampToValueAtTime(.001,t+.09);o.connect(g).connect(c.destination);o.start(t);o.stop(t+.1);}
 voice(kind='maleA',volume=1){const c=this.context();if(!c)return;const now=c.currentTime,breath=kind==='breath'||kind==='heavyBreath',hurt=kind==='hurt'||kind==='heavyHurt';if((breath||hurt)&&now-this.lastVoice<.6)return;this.lastVoice=now;const female=['female','hurt','breath'].includes(kind),heavy=kind.startsWith('heavy'),duration=breath?.45:hurt?.24:heavy?.85:kind==='maleB'?.52:.65,base=heavy?82:female?230:kind==='maleB'?130:165,master=c.createGain();master.gain.setValueAtTime(.001,now);master.gain.linearRampToValueAtTime((breath?.05:hurt?.075:.12)*volume,now+.035);master.gain.exponentialRampToValueAtTime(.001,now+duration);master.connect(c.destination);if(!breath){const glottal=c.createOscillator();glottal.type='sawtooth';glottal.frequency.setValueAtTime(base,now);if(kind==='heavyHoller'){glottal.frequency.exponentialRampToValueAtTime(base*1.45,now+duration*.45);glottal.frequency.exponentialRampToValueAtTime(base*.9,now+duration);}else glottal.frequency.exponentialRampToValueAtTime(base*.53,now+duration);for(const f of [heavy?430:female?850:650,heavy?1000:female?1600:1250]){const formant=c.createBiquadFilter();formant.type='bandpass';formant.frequency.value=f;formant.Q.value=5;glottal.connect(formant).connect(master);}glottal.start();glottal.stop(now+duration);}const air=c.createBufferSource(),filter=c.createBiquadFilter(),airGain=c.createGain();air.buffer=this.noise(c);filter.type='bandpass';filter.frequency.value=breath?1100:800;airGain.gain.value=breath?1:.25;air.connect(filter).connect(airGain).connect(master);air.start(now,this.random302());air.stop(now+duration);}
}
root.NeonAudio={CombatAudio};if(typeof module!=='undefined')module.exports=root.NeonAudio;
})(typeof window!=='undefined'?window:globalThis);
